SOURCE_CLAIM_JSON: {"title":"Egypt: Arrests over calls for protests during COP27 expose reality of human rights crisis","publisher":"Amnesty International","publication_date":"2022-11-06","url":"https://www.amnesty.org/en/latest/news/2022/11/egypt-arrests-over-calls-for-protests-during-cop27-expose-reality-of-human-rights-crisis/","claim":"Ahead of COP27, authorities arrested hundreds over suspected support for protests, searched phone content, enforced disappearances, ignored at least 60 release orders, and confined authorized demonstrations to a camera-monitored area with advance notice and subject-matter restrictions.","locator":"HTML lines 60-70, 73-88","provisional_id":"WEB-3B-002","canonical_fact_key":"https://www.amnesty.org/en/latest/news/2022/11/egypt-arrests-over-calls-for-protests-during-cop27-expose-reality-of-human-rights-crisis/|lines 60-70,73-88|COP27 protest arrests disappearance surveillance and restrictions","disposition":"final_evidence","chapter_ids":["3B"],"methodology_ids":["3B.1","3B.4","3B.5","3B.6","3B.8","3B.9"],"source_type":"international NGO event investigation","source_confidence":"high","source_confidence_reason":"Based on lawyers, former prisoners, relatives, court decisions, and official documents; Amnesty explains its six-month collection method.","final_evidence_use":"final_evidence","period_fit":"Events occurred immediately before and during COP27 in 2022.","ruler_attribution":"Security agencies and the presidency-controlled COP27 framework are attributable at policy level; individual arrests are not shown to have been personally ordered by Sisi.","contrary_evidence":["The reactivated Presidential Pardons Committee released 766 prisoners, but Amnesty documented 1,540 speech- and association-related arrests or questioning over the same broad period."],"lenses":["3B.1","3B.4","3B.5","3B.6","3B.8","3B.9"]}

