SOURCE_CLAIM_JSON: {"title":"UN Country Results Report 2022: Egypt","publisher":"United Nations Country Team in Egypt","publication_date":"2023-07","url":"https://egypt.un.org/sites/default/files/2023-07/2022%20UNCT%20Annual%20Report%20-s.pdf","claim":"In 2022 UN-supported national programs reached more than 15,000 beneficiaries through violence-against-women programming, delivered service packages to 1,046 women and girls affected by violence or harmful practices, supported ten Safe Spaces in five governorates, and helped establish referral and complaint-support mechanisms.","locator":"PDF pages 31-33, lines 2355-2505, especially 2416-2467 and 2482-2505","provisional_id":"WEB-3B-006","canonical_fact_key":"https://egypt.un.org/sites/default/files/2023-07/2022%20UNCT%20Annual%20Report%20-s.pdf|pages 31-33|2022 VAW services safe spaces and referral mechanisms","disposition":"final_evidence","chapter_ids":["3B"],"methodology_ids":["3B.4","3B.7"],"source_type":"intergovernmental program-results report","source_confidence":"high for reported reach; medium for protective effect","source_confidence_reason":"Provides program-specific counts, channels, governorates, and institutional partners, but lacks a population denominator and independent impact evaluation.","final_evidence_use":"final_evidence","period_fit":"All reported program activity is explicitly for 2022.","ruler_attribution":"Programs involved Egyptian ministries, NCW, NCCM, governors, and a prime-ministerial decree; evidence supports administration-level rather than personal presidential attribution.","contrary_evidence":["Reach figures cannot establish prevalence reduction, service quality, or nationwide accessibility.","Several mechanisms were pilots or limited to selected governorates."],"lenses":["3B.4","3B.7"]}

SOURCE_CLAIM_JSON: {"title":"ECWR issues its 2022 Annual Report on the Status of Egyptian Women","publisher":"Egyptian Center for Women’s Rights","publication_date":"2022-12-29","url":"https://ecwronline.org/?p=9709","claim":"ECWR acknowledged continued political support for women's empowerment but reported increased public violence against women, several killings following rejected marriage proposals, and persistently alarming domestic violence, warning that firm protective mechanisms remained necessary.","locator":"HTML lines 94-119, especially 110-115","provisional_id":"WEB-3B-007","canonical_fact_key":"https://ecwronline.org/?p=9709|lines 110-115|2022 positive steps but increased public violence and alarming domestic violence","disposition":"final_evidence","chapter_ids":["3B"],"methodology_ids":["3B.7","3B.10"],"source_type":"domestic civil-society annual report summary","source_confidence":"medium","source_confidence_reason":"Target-year domestic monitoring with specific examples, but the page supplies no denominator or transparent national sampling method.","final_evidence_use":"final_evidence","period_fit":"Direct assessment of calendar year 2022.","ruler_attribution":"Supports outcome/environment assessment, not personal responsibility for private violence.","contrary_evidence":["The report recognized political will, proposed legal reform, and expanded women's access to judicial appointments."],"lenses":["3B.7","3B.10"]}

SOURCE_CLAIM_JSON: {"title":"Sisi orders army to revamp Abu Sefein church","publisher":"Ahram Online","publication_date":"2022-08-14","url":"https://english.ahram.org.eg/NewsContentP/1/473187/Egypt/Sisi-orders-army-to-revamp-Abu-Sefein-church.aspx","claim":"After the Abu Sefein Coptic church fire killed 41 people, Sisi directed the Armed Forces Engineering Authority to reconstruct the church; hospitals received victims, prosecutors opened an investigation, and psychological-support teams were dispatched.","locator":"HTML lines 47-77","provisional_id":"WEB-3B-008","canonical_fact_key":"https://english.ahram.org.eg/NewsContentP/1/473187/Egypt/Sisi-orders-army-to-revamp-Abu-Sefein-church.aspx|lines 47-77|Sisi church-fire reconstruction and state emergency response","disposition":"final_evidence","chapter_ids":["3B"],"methodology_ids":["3B.7","3B.9"],"source_type":"state-aligned domestic news report","source_confidence":"medium-high","source_confidence_reason":"Specific contemporaneous report with named agencies and corroboration from church statements, but dependent on official accounts.","final_evidence_use":"final_evidence","period_fit":"Response occurred on the day of the August 2022 fire.","ruler_attribution":"Direct attribution for reconstruction order; broader emergency response belongs to state agencies.","contrary_evidence":["Residents quoted by independent reporting alleged ambulance and fire-service delays.","The response does not resolve longstanding church-building restrictions or infrastructure deficiencies."],"lenses":["3B.7","3B.9"]}

SOURCE_CLAIM_JSON: {"title":"Egypt: CFJ’s assessment of the first year of the Human Rights Strategy","publisher":"Committee for Justice","publication_date":"2023-04-05","url":"https://www.cfjustice.org/egypt-cfjs-assessment-of-the-first-year-of-the-human-rights-strategy/","claim":"CFJ acknowledged reactivation of the pardon and dialogue committees, reported official reviews releasing 814 pretrial detainees and conditional-release decisions benefiting 20,000 inmates, but concluded that key security and civil-society laws remained unchanged and documented far larger numbers of liberty violations and alleged disappearances.","locator":"HTML lines 38-56, 65-78","provisional_id":"WEB-3B-009","canonical_fact_key":"https://www.cfjustice.org/egypt-cfjs-assessment-of-the-first-year-of-the-human-rights-strategy/|lines 38-56,65-78|2022 releases versus unchanged laws and documented abuses","disposition":"final_evidence","chapter_ids":["3B"],"methodology_ids":["3B.1","3B.4","3B.5","3B.8"],"source_type":"civil-society implementation assessment","source_confidence":"medium","source_confidence_reason":"Directly compares government implementation claims with field documentation, but its very high disappearance count lacks a denominator and full case-level audit on the opened page.","final_evidence_use":"final_evidence","period_fit":"Retrospective assessment specifically covering the strategy's first year and the 2022 Year of Civil Society.","ruler_attribution":"Sisi initiated the strategy-era framing and pardon/dialogue mechanisms; specific violations remain agency-level absent command-chain evidence.","contrary_evidence":["Officially reported releases and conditional releases were material positive actions.","CFJ's counts should not be treated as population prevalence and may differ methodologically from other datasets."],"lenses":["3B.1","3B.4","3B.5","3B.8"]}

